@namespace sv_58b0b8ff70d2465d953eca739f9a5c8a.Components.Pages.Board

<div class="task-card">
    <h4 class="task-card-title">@Task.Title</h4>
    <p class="task-card-assignee">@Task.Assignee</p>
    <span class="task-card-priority priority-@Task.Priority.ToLowerInvariant()">@Task.Priority</span>
    <span class="task-card-due">@Task.DueDate.ToString("MMM dd")</span>
    <div class="task-card-actions">
        @if (CanMoveLeft)
        {
            <button class="btn-move btn-move-left" @onclick="OnMoveLeft">Move Left</button>
        }
        @if (CanMoveRight)
        {
            <button class="btn-move btn-move-right" @onclick="OnMoveRight">Move Right</button>
        }
    </div>
</div>

@code {
    [Parameter, EditorRequired] public TaskItem Task { get; set; } = default!;
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback OnMoveLeft { get; set; }
    [Parameter] public EventCallback OnMoveRight { get; set; }
}

@namespace sv_58b0b8ff70d2465d953eca739f9a5c8a.Components.Pages.Board

@if (!IsVisible)
{
    <button class="btn-add-task" @onclick="Show">Add Task</button>
}
else
{
    <div class="add-task-form">
        <input type="text" placeholder="Title" @bind="title" class="form-input" />
        <input type="text" placeholder="Assignee" @bind="assignee" class="form-input" />
        <select @bind="priority" class="form-input">
            <option value="High">High</option>
            <option value="Medium">Medium</option>
            <option value="Low">Low</option>
        </select>
        <input type="date" @bind="dueDate" class="form-input" />
        <div class="add-task-form-actions">
            <button class="btn-save" @onclick="Save">Save</button>
            <button class="btn-cancel" @onclick="Hide">Cancel</button>
        </div>
    </div>
}

@code {
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnTaskCreated { get; set; }

    private bool IsVisible;
    private string title = string.Empty;
    private string assignee = string.Empty;
    private string priority = "Medium";
    private DateTime dueDate = DateTime.Today.AddDays(7);

    private void Show() => IsVisible = true;

    private void Hide()
    {
        IsVisible = false;
        ResetForm();
    }

    private async Task Save()
    {
        if (!string.IsNullOrWhiteSpace(title))
        {
            await OnTaskCreated.InvokeAsync((title, assignee, priority, dueDate));
            Hide();
        }
    }

    private void ResetForm()
    {
        title = string.Empty;
        assignee = string.Empty;
        priority = "Medium";
        dueDate = DateTime.Today.AddDays(7);
    }
}

@namespace sv_58b0b8ff70d2465d953eca739f9a5c8a.Components.Pages.Board

<div class="kanban-column">
    <div class="kanban-column-header">
        <h3>@Title (@Tasks.Count)</h3>
    </div>
    <div class="kanban-column-body">
        @foreach (var task in Tasks)
        {
            <TaskCard Task="task"
                      CanMoveLeft="CanMoveLeft"
                      CanMoveRight="CanMoveRight"
                      OnMoveLeft="() => OnMoveLeft.InvokeAsync(task.Id)"
                      OnMoveRight="() => OnMoveRight.InvokeAsync(task.Id)" />
        }
    </div>
    <div class="kanban-column-footer">
        <AddTaskForm OnTaskCreated="OnTaskCreated" />
    </div>
</div>

@code {
    [Parameter, EditorRequired] public string Title { get; set; } = string.Empty;
    [Parameter] public List<TaskItem> Tasks { get; set; } = new();
    [Parameter] public bool CanMoveLeft { get; set; }
    [Parameter] public bool CanMoveRight { get; set; }
    [Parameter] public EventCallback<int> OnMoveLeft { get; set; }
    [Parameter] public EventCallback<int> OnMoveRight { get; set; }
    [Parameter] public EventCallback<(string Title, string Assignee, string Priority, DateTime DueDate)> OnTaskCreated { get; set; }
}

@namespace sv_58b0b8ff70d2465d953eca739f9a5c8a.Components.Pages.Board

<div class="task-search-bar">
    <input type="text" placeholder="Search tasks by title..."
           value="@SearchText"
           @oninput="HandleInput"
           class="search-input" />
</div>

@code {
    [Parameter] public string SearchText { get; set; } = string.Empty;
    [Parameter] public EventCallback<string> SearchTextChanged { get; set; }

    private async Task HandleInput(ChangeEventArgs e)
    {
        var value = e.Value?.ToString() ?? string.Empty;
        await SearchTextChanged.InvokeAsync(value);
    }
}

@page "/board"
@namespace sv_58b0b8ff70d2465d953eca739f9a5c8a.Components.Pages.Board
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

@if (isLoading)
{
    <div class="board-loading">Loading tasks...</div>
}
else if (errorMessage is not null)
{
    <div class="board-error">@errorMessage</div>
}
else
{
    <BoardStats Tasks="allTasks" />

    <TaskSearchBar SearchText="@searchText" SearchTextChanged="HandleSearchChanged" />

    <div class="kanban-board">
        <KanbanColumn Title="To Do"
                      Tasks="GetFilteredTasks("To Do")"
                      CanMoveLeft="false"
                      CanMoveRight="true"
                      OnMoveRight="(id) => MoveTask(id, "In Progress")"
                      OnTaskCreated="(t) => CreateTask(t, "To Do")" />

        <KanbanColumn Title="In Progress"
                      Tasks="GetFilteredTasks("In Progress")"
                      CanMoveLeft="true"
                      CanMoveRight="true"
                      OnMoveLeft="(id) => MoveTask(id, "To Do")"
                      OnMoveRight="(id) => MoveTask(id, "Done")"
                      OnTaskCreated="(t) => CreateTask(t, "In Progress")" />

        <KanbanColumn Title="Done"
                      Tasks="GetFilteredTasks("Done")"
                      CanMoveLeft="true"
                      CanMoveRight="false"
                      OnMoveLeft="(id) => MoveTask(id, "In Progress")"
                      OnTaskCreated="(t) => CreateTask(t, "Done")" />
    </div>
}

@code {
    private List<TaskItem> allTasks = new();
    private string searchText = string.Empty;
    private bool isLoading = true;
    private string? errorMessage;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasks();
    }

    private async Task LoadTasks()
    {
        try
        {
            isLoading = true;
            errorMessage = null;
            allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            isLoading = false;
        }
    }

    private void HandleSearchChanged(string value)
    {
        searchText = value;
    }

    private List<TaskItem> GetFilteredTasks(string status)
    {
        var tasks = allTasks.Where(t => t.Status == status);
        if (!string.IsNullOrWhiteSpace(searchText))
        {
            tasks = tasks.Where(t => t.Title.Contains(searchText, StringComparison.OrdinalIgnoreCase));
        }
        return tasks.ToList();
    }

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = allTasks.First(t => t.Id == taskId);
            var index = allTasks.IndexOf(task);
            allTasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to move task: {ex.Message}";
        }
    }

    private async Task CreateTask((string Title, string Assignee, string Priority, DateTime DueDate) form, string status)
    {
        try
        {
            var newTask = await TaskService.CreateTaskAsync(form.Title, form.Assignee, form.Priority, form.DueDate);
            allTasks.Add(newTask with { Status = status });
        }
        catch (Exception ex)
        {
            errorMessage = $"Failed to create task: {ex.Message}";
        }
    }
}

